#!/usr/bin/env node
// Patches OpenNext's build OUTPUT (.open-next/), which is regenerated by every
// `opennextjs-cloudflare build` and therefore can't be fixed by a node_modules
// patch-package patch. Run this after `opennextjs-cloudflare build` and
// before `opennextjs-cloudflare deploy`/`preview` (see the "deploy"/"preview"
// scripts in package.json).
//
// See CLAUDE.md's Hosting section for the full story of why each of these is
// needed. Short version:
//
// 1. Next.js's compiled internals (and Prisma's) still contain real,
//    load-bearing `require("path")`/`require("os")`/etc. calls that OpenNext's
//    build-time AST patches don't eliminate for this Next.js version. esbuild
//    converts each into a runtime helper that checks
//    `typeof require !== "undefined"` and throws "Dynamic require of ... is
//    not supported" otherwise -- always true in Workers, since there's no
//    ambient `require`. Defining a real global `require` in worker.js (via
//    genuine `node:*` static imports, which DO work under Cloudflare's
//    nodejs_compat) makes that helper resolve correctly instead of throwing.
//    "fs" is deliberately not provided: real disk access is impossible in
//    Workers, and the reachable call sites needing it are patched directly in
//    node_modules/next (see patches/next+*.patch) to stub/degrade gracefully.
//
// 2. Prisma's generated client decodes its query-compiler WASM from a base64
//    string and calls `new WebAssembly.Module(bytes)` at runtime -- Cloudflare
//    Workers disallows dynamic WASM compilation from raw bytes. The fix:
//    import a real `.wasm` file instead (materialized by
//    scripts/materialize-prisma-wasm.mjs), which Wrangler's bundler compiles
//    at build time, so no runtime compile step is needed. This has to be
//    patched into the *compiled* output because Turbopack's own `.wasm`
//    import handling only accepts files with its own companion-loader naming
//    convention, so patching the TypeScript source directly breaks the
//    Turbopack build itself (see CLAUDE.md for the full story).

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

const require = createRequire(import.meta.url);

const openNextDir = path.join(process.cwd(), ".open-next");
const handlerPath = path.join(openNextDir, "server-functions/default/handler.mjs");
const workerPath = path.join(openNextDir, "worker.js");

for (const p of [handlerPath, workerPath]) {
  if (!existsSync(p)) {
    console.error(`[postbuild-cloudflare-patches] expected file not found: ${p}`);
    console.error("Run `opennextjs-cloudflare build` first.");
    process.exit(1);
  }
}

// --- 1. Patch the WASM query-compiler loader in handler.mjs ---

const wasmBase64ModulePath = require.resolve("@prisma/client/runtime/query_compiler_fast_bg.postgresql.wasm-base64.js");
const wasmPath = path.join(path.dirname(wasmBase64ModulePath), "query_compiler_fast_bg.postgresql.wasm");
if (!existsSync(wasmPath)) {
  console.error(`[postbuild-cloudflare-patches] expected WASM file not found: ${wasmPath}`);
  console.error("Run `npm install` (or `node scripts/materialize-prisma-wasm.mjs`) first.");
  process.exit(1);
}

let handlerContent = readFileSync(handlerPath, "utf8");
const wasmLoaderPattern = /getQueryCompilerWasmModule:async\(\)=>\{let\{wasm:(\w+)\}=await (\w+)\.A\(80599\);return await (\w+)\(\1\)\}/g;
const wasmReplacement = (match, varname) =>
  `getQueryCompilerWasmModule:async()=>{let ${varname}=await import(${JSON.stringify(wasmPath)});return ${varname}.default}`;

const wasmMatches = [...handlerContent.matchAll(wasmLoaderPattern)];
if (wasmMatches.length === 0) {
  console.error(
    "[postbuild-cloudflare-patches] WASM loader pattern not found in handler.mjs.\n" +
      "This likely means a Next.js/Prisma/Turbopack version bump changed the compiled\n" +
      "output shape. Re-diagnose (see CLAUDE.md's Hosting section) and update the\n" +
      "regex in this script.",
  );
  process.exit(1);
}
handlerContent = handlerContent.replace(wasmLoaderPattern, wasmReplacement);
writeFileSync(handlerPath, handlerContent);
console.log(`[postbuild-cloudflare-patches] patched ${wasmMatches.length} WASM loader occurrence(s) in handler.mjs`);

// --- 2. Insert the node: imports + global require() shim into worker.js ---

let workerContent = readFileSync(workerPath, "utf8");

if (workerContent.includes("globalThis.require")) {
  console.log("[postbuild-cloudflare-patches] worker.js already patched, skipping shim insertion");
} else {
  const NODE_BUILTINS = [
    "path",
    "os",
    "url",
    "util",
    "crypto",
    "buffer",
    "stream",
    "events",
    "assert",
    "querystring",
    "child_process",
    "http",
    "https",
    "zlib",
    "dns",
    "perf_hooks",
    "async_hooks",
    "diagnostics_channel",
    "string_decoder",
    "timers",
    "timers/promises",
    "stream/web",
    "stream/promises",
    "stream/consumers",
    "module",
    "vm",
  ];
  // "fs"/"fs/promises"/"util/types" are handled separately: real fs.* access is
  // impossible in Workers, but Next's own module-load-time `require("fs")`
  // calls are already patched to degrade gracefully in node_modules (see
  // patches/next+*.patch) -- providing a *working* "node:fs" here (rather
  // than leaving it to throw) is what actually resolves the Hyperdrive/pg
  // require chain elsewhere in the bundle, so it's included, just kept
  // separate from the "no real fs semantics" builtins above for clarity.
  const EXTRA_BUILTINS = ["fs", "fs/promises", "util/types"];

  const varNameFor = (id) =>
    "node" +
    id
      .split(/[^a-zA-Z]+/)
      .filter(Boolean)
      .map((word) => word[0].toUpperCase() + word.slice(1))
      .join("");

  const imports = [...NODE_BUILTINS, ...EXTRA_BUILTINS]
    .map((id) => `import ${varNameFor(id)} from "node:${id}";`)
    .join("\n");

  const cases = [...NODE_BUILTINS, ...EXTRA_BUILTINS]
    .map((id) => {
      const varName = varNameFor(id);
      if (id === "fs" || id === "fs/promises") {
        // Only "node:fs"/"node:fs/promises" (not bare "fs"/"fs/promises") --
        // the bare specifiers are left to the default throw case below, since
        // the only call sites reaching bare "fs" are the ones already patched
        // in node_modules to tolerate a throw (see patches/next+*.patch).
        return `            case "node:${id}":\n                return ${varName};`;
      }
      return `            case ${JSON.stringify(id)}:\n            case ${JSON.stringify("node:" + id)}:\n                return ${varName};`;
    })
    .join("\n");

  const shim = `
// See scripts/postbuild-cloudflare-patches.mjs for the full explanation.
if (typeof globalThis.require === "undefined") {
    globalThis.require = function require(id) {
        switch (id) {
${cases}
            default:
                throw new Error(\`Dynamic require of "\${id}" is not supported\`);
        }
    };
}
export default {`;

  // Insert imports right after the first existing import line, and the shim
  // right before the `export default {` that starts the fetch handler.
  const firstImportMatch = workerContent.match(/^(\/\/[^\n]*\n)?import .+;\n/m);
  if (!firstImportMatch) {
    console.error("[postbuild-cloudflare-patches] could not find an import statement to anchor the node: imports in worker.js");
    process.exit(1);
  }
  const insertAt = firstImportMatch.index;
  workerContent = workerContent.slice(0, insertAt) + imports + "\n" + workerContent.slice(insertAt);

  if (!workerContent.includes("export default {")) {
    console.error("[postbuild-cloudflare-patches] could not find `export default {` to anchor the require() shim in worker.js");
    process.exit(1);
  }
  workerContent = workerContent.replace("export default {", shim);

  writeFileSync(workerPath, workerContent);
  console.log("[postbuild-cloudflare-patches] inserted node: imports + global require() shim into worker.js");
}
